package ru.portfolio.finance;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate;
@Entity public class Transaction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private BigDecimal amount; @Column(nullable=false) private String category; @Column(nullable=false) private LocalDate transactionDate; private String description; public Transaction(){} public Transaction(BigDecimal a,String c,LocalDate d,String x){amount=a;category=c;transactionDate=d;description=x;} public Long getId(){return id;} public BigDecimal getAmount(){return amount;} public String getCategory(){return category;} public LocalDate getTransactionDate(){return transactionDate;} public String getDescription(){return description;} }
